const o=/\bp[1-5]-(?:target|question|item|choice|option|colour|color|blank)-[a-z0-9-]{8,}\b/i,s=/\{\{[a-zA-Z0-9_-]+\}\}/g;function a(r,t){const n=Number(r);return Number.isInteger(n)&&n>=1&&n<=5?n:Math.min(5,Math.max(1,Math.floor(Math.max(0,t)/5)+1))}function u(r,t){const n=a(r,t),e=Math.max(0,t)%5+1;return n===1?`Part 1 · Vị trí nhân vật ${e}`:n===5?`Part 5 · Vùng tô màu ${e}`:`Part ${n} · Câu ${e}`}function c(r,t,n){const i=String(r??"").trim().replace(s,"_____").replace(/\s*[•]\s*/g," · ").replace(/\s+/g," ").trim();return!i||o.test(i)?u(t,n):i}function f(r){const t=String(r??"").trim();return t?o.test(t)?"Không có dữ liệu hiển thị":t:""}export{f as a,c as f};
